export const PUBLIC_WORKER_B_PREFIXES = [
  "/posts",
  "/feed",
  "/img/",
  "/users/",
  "/health",
  "/.well-known/",
  "/api/follower-tokens",
  "/api/media/tickets",
  "/interactions/",
  "/dm/",
  "/groups/"
];

export function isAllowedOwnerPath(method, pathname) {
  const normalizedMethod = method.toUpperCase();
  for (const rule of OWNER_GATEWAY_RULES) {
    if (rule.match === 'exact') {
      if (pathname === rule.path && rule.methods.includes(normalizedMethod)) return true;
      continue;
    }
    if (pathname.startsWith(rule.pathPrefix) && rule.methods.includes(normalizedMethod)) return true;
  }
  return false;
}

export function isPublicWorkerBPath(pathname) {
  return PUBLIC_WORKER_B_PREFIXES.some((prefix) => {
    // 以 / 结尾的前缀（如 /groups/）目录根留给前端静态页，禁止整页相等命中误代理
    if (prefix.endsWith('/')) {
      return pathname.startsWith(prefix) && pathname.length > prefix.length;
    }
    return pathname === prefix || pathname.startsWith(prefix + '/');
  });
}
